const aoState={filter:'全部',preview:'正常',agents:{},comments:{},converted:[]};
function aoEsc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function aoBtn(t,fn,cls='',disabled=false,reason=''){return `<button type="button" class="btn ${cls}" onclick="${aoEsc(fn)}" ${disabled?'disabled':''}>${t}</button>${disabled?`<span class="muted xs">${aoEsc(reason)}</span>`:''}`;}
function aoKv(rows){return `<dl class="kv">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl>`;}
function aoTable(cols,rows){return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
