PAGES['agent-ops']=(arg)=>head('治理','Agent 操作清单','返回结果都带 next；权限不足返回 CAPABILITY_NOT_AUTHORIZED，对应治理原因码。')+card('协议与范围',aoKv([['清单依据','D120 · 操作清单原型'],['授权原则','默认拒绝；每次操作独立检查权限、委托与配额'],['写入协议','上下文已有更新 → interrupted → 重读 → 同一幂等键重试'],['字段说明','Schema 是可展开摘要；未定权限明确标记，不构成新授权']]))+card('可调用操作',`<div class="row wrap">${['全部','有副作用','需人确认'].map(t=>`<button class="chip ${aoState.filter===t?'on':''}" onclick="aoSet('filter','${t}')">${t}</button>`).join('')}</div><div class="sep"></div>${aoTable(['操作名','输入参数 · JSON Schema','副作用','幂等 / 幂等键','权限码','可否委托','返回 next 示例'],aoOps.filter(o=>aoState.filter==='全部'||aoState.filter==='有副作用'&&o[1]!=='inbox_read'||aoState.filter==='需人确认'&&o[6]).map(o=>[`${o[0]}<div class="mono xs">${o[1]}</div>`,`<details><summary>展开 ${Object.keys(o[2]).length} 个参数</summary><pre class="code">${aoEsc(JSON.stringify({type:'object',required:Object.keys(o[2]),properties:Object.fromEntries(Object.entries(o[2]).map(([k,v])=>[k,v.includes('|')?{enum:v.split(' | ')}:{type:v}])),additionalProperties:false},null,2))}</pre></details>`,o[3],o[1]==='inbox_read'?'是 · 只读，无需幂等键':`是 · <span class="mono">Idempotency-Key: ${o[1]}-001</span>`,aoEsc(o[4]),o[5]?'是 · 受范围与策略约束':'否',`<code>${aoEsc(JSON.stringify({next:[{operation:o[7]}]}))}</code>`]))}`)+card('状态预览与治理结果',`<div class="row wrap"><span>状态预览</span>${['正常','异常','空'].map(t=>`<button class="chip ${aoState.preview===t?'on':''}" onclick="aoSet('preview','${t}')">${t}</button>`).join('')}</div><div class="sep"></div>${aoState.preview==='空'?'<div class="empty">当前身份没有可调用操作；请联系负责人核对授权。</div>':aoState.preview==='异常'?'<div class="note danger">CAPABILITY_NOT_AUTHORIZED · 原因码 HUMAN_ONLY：Agent 不可执行仅人类操作。next：请求有权限的人处理。</div>':'<div class="note ok">认领成功 · 工作项 BIL-144 · 游标 1042 · next：读取工作上下文。</div>'}<p class="muted small">清单为 Mock；D120 新增操作的最终 API 与权限码尚待规格定稿。</p>`);
TITLES['agent-ops']='Agent 操作清单';
/* 独立治理页按要求不设置 NAVPARENT。 */
function aoAgent(k){return aoState.agents[k]||(aoState.agents[k]={actor:'负责人',status:flAgentStatus(k)==='STOPPED'?'离线':'工作中',changed:'2026-10-12 09:30',events:[['09:30','工作中','处理工作上下文'],['09:18','思考中','读取任务契约'],['09:17','在线','执行机报告上线']],session:true,workspace:true,wake:'提示流',cursor:1042,unread:2,reads:false,loop:'每日站会摘要',cadence:'每天 18:00',checks:'核对系统进度与声明状态；列出未验证项',budget:'5',escalation:'预算阈值、Andon 停线或需求冲突升级给负责人',format:'摘要、阻塞、证据链接、未验证项',saved:false});}
function aoAgentSet(k,key,value){aoAgent(k)[key]=value;route();}
function aoAccess(k){return ['负责人','管理员'].includes(aoAgent(k).actor);}
function aoLifecycleBody(k){const a=aoAgent(k),m=MACHINES.find(m=>m.n===PEOPLE[k].machine),available=flMStatus(m)==='ONLINE'&&flAgentStatus(k)!=='STOPPED',manage=aoAccess(k);return card('生命周期 · 执行机报告',`<div class="row wrap">${['在线','思考中','工作中','出错','离线'].map(t=>`<span class="badge ${a.status===t?'b-primary':'b-stale'}">${t}</span>`).join('')}</div>${aoKv([['当前状态',a.status],['最近变化',a.changed],['报告来源',m.n+' · runner'],['会话',a.session?'保留 · S-'+k:'已清空'],['工作区',a.workspace?'保留 · /workspaces/'+k:'已清空']])}<p class="muted small">生命周期五态与编制状态独立；原型不主动伪造 runner 心跳。</p>`)+card('最近变化时间线',aoTable(['时间','状态','变化原因'],a.events))+card('重置与身份',`<label class="stack">身份预览<select class="select" onchange="aoAgentSet('${k}','actor',this.value)">${['负责人','管理员','其他人','Agent'].map(t=>`<option ${a.actor===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="sep"></div><div class="row wrap">${aoBtn('重启（保留会话）',`aoReset('${k}','restart')`,'',!available||!manage,!manage?'你不是负责人或管理员':'机器离线、已吊销或 Agent 已停止')}${aoBtn('清空会话（保留工作区）',`aoReset('${k}','session')`,'',!available||!manage,!manage?'你不是负责人或管理员':'机器离线、已吊销或 Agent 已停止')}${aoBtn('完全重置',`aoReset('${k}','full')`,'danger',!available||!manage,!manage?'仅有管理权限的人类可操作':'机器离线、已吊销或 Agent 已停止')}</div><div class="note danger">清空会话会丢失上下文，但保留工作区；完全重置会清空会话和工作区，未保存产物无法恢复，仅人类可操作并需重新认证。</div>`)+card('工作区与记忆查看器',!manage?'<div class="note warn">仅该 Agent 的负责人与管理员可见；你当前身份不能读取工作区与记忆。</div>':`${a.workspace?`<details open><summary>工作区文件树 · /workspaces/${aoEsc(k)}</summary><div class="stack mono"><span>src / export.mjs</span><span>exports / billing.csv</span><span>notes / context.md</span></div></details><pre class="code">src/export.mjs L42–L48\n导出字段：账期、金额、税额；权限：财务角色。</pre>`:'<div class="empty">工作区已清空，等待重新初始化。</div>'}${aoTable(['记忆条目','类型','来源','状态'],[['金额使用整数分','经验','BIL-139 · 提交 9f3c2a1','有效'],['导出前复验角色权限','规则','Morgan 审批 · MA-22','有效']])}<p class="muted xs">完全重置不撤销独立管理的长期记忆。</p>`);}
function aoReset(k,type){const a=aoAgent(k),m=MACHINES.find(m=>m.n===PEOPLE[k].machine);if(!aoAccess(k)||flMStatus(m)!=='ONLINE'||flAgentStatus(k)==='STOPPED')return toast('当前身份或运行状态不允许重置');const text={restart:'重启保留会话与工作区，当前进程会重新启动。',session:'清空会话上下文，保留工作区；未保存上下文无法恢复。',full:'会话与工作区都将清空，未保存产物无法恢复；仅人类、需重新认证。'}[type];openModal(card('确认重置',`<div class="note ${type==='full'?'danger':type==='session'?'warn':'info'}">${text}</div><p>你正在操作 ${aoEsc(PEOPLE[k].n)}。${type==='full'?'这是原型认证演示，不校验真实凭证。':''}</p>${aoBtn('取消','closeModal()')}${aoBtn(type==='full'?'模拟重新认证并确认':type==='session'?'确认清空会话':'确认重启',`aoConfirmReset('${k}','${type}')`,type==='full'?'danger':'primary')}`));}
function aoConfirmReset(k,type){if(!aoAccess(k))return toast('身份已变化，不能重置');const a=aoAgent(k);if(type!=='restart')a.session=false;if(type==='full')a.workspace=false;a.status='在线';a.changed='刚刚（演示）';a.events.unshift([a.changed,'在线',{restart:'重启，保留会话',session:'清空会话，保留工作区',full:'人类重新认证后完全重置'}[type]]);closeModal();route();toast('重置已记录（演示）');}
function aoInboxBody(k){const a=aoAgent(k);return card('持久收件箱',aoKv([['Agent','@'+aoEsc(k)],['单一事实源','持久事件收件箱'],['当前游标 since',a.cursor],['未读事件数',a.unread]])+aoBtn('重读并按游标确认',`aoReadInbox('${k}')`,'primary',!a.unread,'没有未读事件'))+card('唤醒协议',`<label class="stack">唤醒方式<select class="select" onchange="aoAgentSet('${k}','wake',this.value)">${['轮询','提示流','签名 webhook'].map(t=>`<option ${a.wake===t?'selected':''}>${t}</option>`).join('')}</select></label>${aoKv([['当前方式',a.wake],['轮询间隔','30 秒'],['提示流心跳','15 秒；断开后按游标补读'],['webhook 校验','签名 + 时间戳；内容从收件箱重读']])}<div class="note info">唤醒只带提示，不携带事件内容；收到提示后以 since 读取，读取后按游标确认。</div>`)+card('最近写入记录',aoTable(['时间','操作 / 幂等键','结果'],[['09:31','发送消息 · msg-1042','interrupted：写入时会话已有 2 条更新消息 → 已重读并以同一幂等键重试成功'],['09:30','提交完成声明 · claim-1041','已声明完成（未验证）；next：读取平台验证结果'],['09:18','认领工作项 · claim-1038','成功；next：读取工作上下文'],...(a.reads?[['刚刚','读取收件箱 · since 1042','重读 2 条事件；确认游标 1044；next：处理提醒']]:[])]));}
function aoReadInbox(k){const a=aoAgent(k);if(!a.unread)return;a.cursor+=a.unread;a.unread=0;a.reads=true;route();toast('已重读并确认游标（演示）');}
function aoLoopsBody(k){const a=aoAgent(k);return card('提醒列表 · 锚定 thread',aoTable(['提醒','线程锚点','节奏 / 下次触发','状态'],[['每日站会摘要','thread:BIL-142-standup','每天 18:00 · 今天 18:00','已启用'],['周报草稿','thread:team-weekly','每周五 · 10-16 18:00','已启用']]))+card('循环约定编辑器',`<form onsubmit="event.preventDefault();aoSaveLoop('${k}',this)"><div class="stack"><label>示例<select class="select" name="loop" onchange="aoLoopExample('${k}',this.value)">${['每日站会摘要','周报草稿'].map(t=>`<option ${a.loop===t?'selected':''}>${t}</option>`).join('')}</select></label><label>节奏<select class="select" name="cadence">${['每天 18:00','每周五'].map(t=>`<option ${a.cadence===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="stack">自检规则<textarea name="checks" required maxlength="2000">${aoEsc(a.checks)}</textarea></label><label>预算上限（美元 / 次）<input name="budget" type="number" min="0.01" step="0.01" required value="${aoEsc(a.budget)}"></label><label class="stack">升级条件<textarea name="escalation" required maxlength="2000">${aoEsc(a.escalation)}</textarea></label><label class="stack">输出格式<textarea name="format" required maxlength="2000">${aoEsc(a.format)}</textarea></label><button class="btn primary" type="submit">保存循环约定</button></div></form>${a.saved?'<div class="note ok">循环约定已保存到浏览器内存。</div>':''}`)+card('执行与确认边界',aoKv([['当前约定',aoEsc(a.loop)],['线程锚点',a.loop==='周报草稿'?'thread:team-weekly':'thread:BIL-142-standup'],['时区','团队时区 · 每周五默认 18:00'],['驱动方式','到点提醒写入持久收件箱，再唤醒 Agent'],['输出状态','草稿；人类确认后才成为正式报告']])+'<div class="note info">预算越界、停线或需求冲突升级给负责人；内部质量返工不直接通知人或甲方。Agent 不可确认计划、报告或接受交付物。</div>');}
function aoLoopExample(k,t){const a=aoAgent(k);a.loop=t;a.cadence=t==='周报草稿'?'每周五':'每天 18:00';a.saved=false;route();}
function aoSaveLoop(k,form){const data=new FormData(form);if(!['checks','escalation','format'].every(f=>String(data.get(f)).trim())||Number(data.get('budget'))<=0)return toast('请填写有效的循环约定');Object.assign(aoAgent(k),Object.fromEntries(data),{saved:true});route();toast('循环约定已保存（演示）');}
const aoAnchors={code:'src/export.mjs L42–L48',text:'src/export.mjs L42–L48',csv:'exports/billing.csv · 第 2 行',web:'选择器 #export-panel · 视口 375 · 矩形 x24 y80 w327 h160',video:'renders/master.mp4 · 时间点 00:12.4',novel:'chapters/01.md · 第 1 章 · 第 2 段'};
function aoComments(kind){if(!aoAnchors[kind])return card('锚定批注','<div class="note info">当前产物类型未提供 D120 锚点；请切换网页、CSV、视频或小说。代码 / 文本锚点示例可在下方选择。</div>'+aoBtn('查看代码 / 文本锚点',"aoCommentKind('code')"));const list=aoState.comments[kind]||(aoState.comments[kind]=[{anchor:aoAnchors[kind],version:'9f3c2a1',author:'你 · 人',body:'请核对这里的导出字段与验收标准。',replies:['Ada · Agent：已记录，补充验证证据后回复。'],actions:[]}]);const changed=rmState.version==='当前工作区';return card('锚点选择',`<div class="row wrap">${Object.entries({code:'代码 / 文本',csv:'CSV 行',web:'网页区域',video:'视频（v1.1）',novel:'小说（v1.1）'}).map(([v,t])=>aoBtn(t,`aoCommentKind('${v}')`,kind===v?'primary sm':'ghost sm')).join('')}</div><div class="sep"></div><label class="stack">锚点<input id="ao-anchor" value="${aoEsc(aoAnchors[kind])}"></label>${kind==='web'?'<div style="border:2px dashed var(--border-strong);padding:18px;margin-top:12px">选中网页区域 · #export-panel<br>选择器 + 视口 375 · x24 y80 w327 h160</div>':''}<p class="muted small">示例锚点选择；保留路径、行区间 / 行 / 区域 / 时间点 / 段落与提交版本。</p>`)+card('批注与回复',list.map((c,n)=>`<div class="stack"><b>${aoEsc(c.anchor)}</b><span class="small">${aoEsc(c.author)} · 所在版本：提交 ${aoEsc(c.version)}</span>${changed&&c.version==='9f3c2a1'?'<span class="badge b-stale">锚点所在版本已更新</span>':''}<div class="bubble">${aoEsc(c.body)}</div>${c.replies.map(r=>`<div class="bubble">回复 · ${aoEsc(r)}</div>`).join('')}<label class="stack">回复内容<input id="ao-reply-${n}" maxlength="2000"></label>${aoBtn('回复',`aoReply('${kind}',${n})`,'sm')}<div class="row wrap">${aoBtn('转为评审意见',`aoConvert('${kind}',${n},'评审意见')`,'sm',c.actions.includes('评审意见'),'已转换，保留原始锚点')}${aoBtn('提为缺陷',`aoConvert('${kind}',${n},'缺陷')`,'sm',c.actions.includes('缺陷'),'已转换，保留原始锚点')}${aoBtn('加入甲方拒收项','','sm',true,'这里只是内部预览，不是甲方验收场景')}</div>${c.actions.map(t=>`<div class="note ok">已转为${t}（内存草稿） · 原锚点 ${aoEsc(c.anchor)} · 提交 ${aoEsc(c.version)}</div>`).join('')}</div><div class="sep"></div>`).join(''))+card('新增锚定批注',`<label class="stack">批注内容<textarea id="ao-comment" maxlength="2000"></textarea></label>${aoKv([['作者','你 · 人'],['版本',changed?'当前工作区快照（未提交）':'提交 9f3c2a1'],['可见范围','项目内部；不暴露给甲方']])}${aoBtn('写入批注',`aoAddComment('${kind}')`,'primary')}`);}
function aoCommentKind(kind){aoState.commentKind=kind;aoState.commentItem=rmState.item;route();}
function aoAddComment(kind){const body=document.getElementById('ao-comment').value.trim(),anchor=document.getElementById('ao-anchor').value.trim();if(!body||!anchor)return toast('请填写锚点与批注内容');aoState.comments[kind].push({anchor,version:rmState.version==='当前工作区'?'工作区快照':'9f3c2a1',author:'你 · 人',body,replies:[],actions:[]});route();toast('批注已写入（演示）');}
function aoReply(kind,n){const text=document.getElementById('ao-reply-'+n).value.trim();if(!text)return toast('请填写回复内容');aoState.comments[kind][n].replies.push('你 · 人：'+text);route();}
function aoConvert(kind,n,target){const c=aoState.comments[kind][n];if(c.actions.includes(target))return;c.actions.push(target);aoState.converted.push({type:target,anchor:c.anchor,version:c.version,body:c.body});route();toast('已创建'+target+'草稿，保留锚点与版本（演示）');}
